<?php require_once 'config.php'; if (logged_in()) redirect('dashboard.php');
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $name = trim($_POST['name'] ?? ''); $email = strtolower(trim($_POST['email'] ?? '')); $password = $_POST['password'] ?? '';
  if (strlen($name) < 2 || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 6) { flash('error', 'Please enter your name, a valid email, and a password with at least 6 characters.'); redirect('register.php'); }
  try { db()->prepare('INSERT INTO users (name,email,password_hash) VALUES (?,?,?)')->execute([$name,$email,password_hash($password, PASSWORD_DEFAULT)]); flash('success', 'Your quest starts now. Please log in.'); redirect('login.php'); } catch (PDOException $e) { flash('error', 'An account already uses that email.'); redirect('register.php'); }
} require 'header.php'; ?>
<section class="auth"><div class="auth-note"><p class="eyebrow">Join the movement</p><h1>Leave a little<br>good behind.</h1><p>Every small action counts. Build a brighter routine with a community that notices.</p><div class="quote">“The smallest kind gesture can make a lasting ripple.”</div></div><form class="auth-card" method="post"><p class="eyebrow">Create account</p><h2>Your first step</h2><label>Your name<input required name="name" maxlength="100" placeholder="Your full name"></label><label>Email address<input required type="email" name="email" placeholder="you@example.com"></label><label>Password<input required type="password" name="password" minlength="6" placeholder="At least 6 characters"></label><button class="button" type="submit">Start my quest →</button><p class="form-note">Already a member? <a href="login.php">Log in</a></p></form></section>
